import {batchData,batchGradient,batchInitial,nextBatch,fitTrain,fitValidation,fitPolynomial,evaluateHoldout} from './ai-training-model.js';
const $=id=>document.getElementById(id),fmt=v=>v.toFixed(5),seen=new Set();let s,scene,revision=0;
const content={batch:{title:'Batch / Epoch · หนึ่งรอบฝึกเกิดอะไรขึ้น',intro:'ข้อมูล8ตัวอย่างไม่ได้แปลว่าต้องอัปเดต8ครั้งเสมอ เราเลือก Batch คำนวณ Gradient เฉลี่ย แล้วอัปเดต w,b หนึ่งครั้ง เมื่อใช้ข้อมูลครบ8ตัวอย่างจึงจบหนึ่ง Epoch ปุ่มเล่นภาพแค่ย้อนดูรอบที่คำนวณแล้ว ไม่เพิ่มการฝึก',terms:[['Dataset','ชุดตัวอย่างพร้อมคำตอบสำหรับการฝึก'],['Batch size','จำนวนตัวอย่างที่รวมในหนึ่งการอัปเดต'],['Gradient เฉลี่ย','เฉลี่ยความไวของ Loss จากตัวอย่างในBatchเดียวกัน'],['Epoch / Update','Epoch=ผ่านชุดฝึกครบหนึ่งรอบ; Update=ปรับพารามิเตอร์หนึ่งครั้ง']],limits:'โมเดลเส้นตรง ŷ=wx+b ไม่ใช่โครงข่าย17พารามิเตอร์ ใช้ข้อมูล8ตัวอย่างลำดับคงที่ ไม่มีshuffle/gradient accumulation/distributed training ตาราง Loss ทั้งชุดไม่ใช่เฉพาะBatch ปรับ Batch size จะเริ่มพารามิเตอร์ใหม่ให้เปรียบเทียบเท่าเทียม',source:'https://docs.pytorch.org/tutorials/beginner/basics/optimization_tutorial.html',steps:['ตัวอย่างที่อยู่ใน Batch','คำนวณ Gradient เฉลี่ย','อัปเดตพารามิเตอร์หนึ่งครั้ง'],task:'ใช้ Batch size2 กด “ฝึกครบหนึ่ง Epoch” ดู8ตัวอย่าง/4Updates จากนั้นเปลี่ยน Batch size8 (เริ่มใหม่อัตโนมัติ) ฝึกหนึ่งEpoch ดู1Update ต้องทดลองครบสองขนาดและมีEpochครบก่อนตรวจ'},fit:{title:'Validation / Overfitting · เก่งกับข้อมูลใหม่ไหม',intro:'เส้นโค้งที่ตามจุดฝึกได้ทุกจุดอาจตาม Noise ด้วย ลองพหุนาม Degree1/3/7 ที่ fit จากชุดฝึกเดียวกัน แล้วดู MSE ของ Validation ที่ไม่ใช้หาพารามิเตอร์ เลือกโมเดลด้วย Validation ก่อนเปิดผล Test สุดท้าย',terms:[['Training split','ชุดที่ใช้คำนวณพารามิเตอร์จริง'],['Validation split','ชุดแยกสำหรับเปรียบเทียบตัวเลือกโมเดล'],['Degree / Capacity','ดีกรีสูงขึ้นเพิ่มจำนวนพารามิเตอร์และความยืดหยุ่น'],['Overfitting / Test split','ตามชุดฝึกมากจนทั่วไปไม่ดี; Testคือชุดประเมินสุดท้าย ไม่ใช้เลือกโมเดล']],limits:'Regression polynomial least squares ด้วยQRจริง ไม่ใช่Neural gradient training/early stopping ข้อมูลสังเคราะห์8Train/9Validation/11Test ดีกรี7มี8พารามิเตอร์ ความผิดพลาดต่ำในชุดเดียวไม่รับประกันผลทั่วไป Testล็อกโมเดลหลังเปิด ห้ามจูนจากผลTest',source:'https://scikit-learn.org/stable/modules/learning_curve.html',steps:['ชุดฝึก: fit เส้นจากข้อมูล','ชุด Validation: ใช้เส้นเดิมทาย','เปรียบเทียบ Loss ก่อนเลือกโมเดล'],task:'เลือก Degree1 แล้ว Degree7 ดู TrainกับValidation จนขั้น3ทั้งสองกรณี สังเกตว่า7ตามTrainได้ดีแต่Validationไม่ดีกว่าเสมอ จากนั้นเลือกDegree3 และกด “ประเมิน Test สุดท้าย” จึงตรวจภารกิจ'}};
function fresh(topic){return {topic,revision:++revision,step:0,playing:false,speed:Number($('speed').value),batch:batchInitial(),rate:.1,record:null,fit:fitPolynomial(1),holdout:null};}
function render(){const c=content[s.topic];$('scene-title').textContent=c.steps[s.step];$('step').textContent=`${s.step+1}/3 · ${c.steps[s.step]}`;$('play').textContent=s.playing?'Ⅱ หยุด':'▶ เล่นภาพ';$('previous').disabled=s.step===0;$('next').disabled=s.step===2;
 if(s.topic==='batch'){const p=s.batch,r=s.record;$('result').innerHTML=`<p class="metric">Epoch ${p.epoch} · Updates ${p.updates} · ใช้ ${p.cursor}/8 ตัวอย่างในรอบปัจจุบัน</p><p>w=${fmt(p.w)} · b=${fmt(p.b)} · MSEทั้งชุด ${fmt(batchGradient(p.w,p.b,batchData).loss)}</p>${r?`<p>Batchล่าสุด IDs [${r.data.map(p=>p.id)}] · Gradientเฉลี่ย dw=${fmt(r.g.dw)} / db=${fmt(r.g.db)}</p><p>w: ${fmt(r.before.w)} → ${fmt(p.w)} · b: ${fmt(r.before.b)} → ${fmt(p.b)}</p>`:'<p>ยังไม่มีการฝึก กดคำนวณ Batch ก่อน เล่นภาพไม่เพิ่ม Updates</p>'}`;}
 else{const f=s.fit;if(s.step===2)seen.add('degree'+f.degree);$('result').innerHTML=`<p class="metric">Degree ${f.degree} · ${f.coeff.length} พารามิเตอร์</p><p>Train MSE ${fmt(f.trainLoss)} · Validation MSE ${fmt(f.validationLoss)}</p><p>${s.holdout?`Test MSE ${fmt(s.holdout.loss)} · ${s.holdout.count} ตัวอย่าง · ล็อกตัวเลือกแล้ว`:'Test ยังไม่เปิด · ใช้ Validation เลือกโมเดลก่อน'}</p><details><summary>ดูพารามิเตอร์พหุนาม</summary><p>ŷ = Σ cₖxᵏ · c = [${f.coeff.map(fmt)}]</p></details><p>เขียว=Train · ม่วง=Validation · เส้นทอง=ค่าทำนาย · เส้นสั้นแนวตั้ง=Error ไม่ใช่เส้นทางPacket</p>`;}
 $('result').insertAdjacentHTML('beforeend',s.topic==='batch'?'<p>Learning rate η = 0.1 คงที่ · ปุ่มความเร็วเปลี่ยนเฉพาะภาพ ไม่เพิ่มการฝึก</p>':'<p>แสดงทศนิยม5ตำแหน่ง: 0.00000 อาจเป็นค่าบวกเล็กมาก ไม่ใช่รับประกันว่าErrorศูนย์แน่นอน</p>');
}
function button(text,id,fn){const b=document.createElement('button');b.textContent=text;b.id=id;b.onclick=fn;$('inputs').append(b);}
function controls(){ $('inputs').replaceChildren();if(s.topic==='batch'){const l=document.createElement('label');l.textContent='Batch size';const sel=document.createElement('select');[2,4,8].forEach(v=>sel.add(new Option(v,v)));sel.value=s.batch.size;sel.onchange=()=>{s.batch=batchInitial(Number(sel.value));s.record=null;s.step=0;s.playing=false;s.revision++;$('feedback').textContent='เริ่มพารามิเตอร์ใหม่สำหรับขนาดBatchที่เลือก';render();};l.append(sel);$('inputs').append(l);button('คำนวณ Batch ถัดไป','batch-next',()=>train(false));button('ฝึกครบหนึ่ง Epoch','epoch',()=>train(true));}
 else {const l=document.createElement('label');l.textContent='Degree';const sel=document.createElement('select');[1,3,7].forEach(v=>sel.add(new Option(v,v)));sel.value=s.fit.degree;sel.disabled=Boolean(s.holdout);sel.onchange=()=>{s.fit=fitPolynomial(Number(sel.value));s.step=0;s.playing=false;s.revision++;render();};l.append(sel);$('inputs').append(l);button('ประเมิน Test สุดท้าย','test',()=>{s.holdout=evaluateHoldout(s.fit.coeff);s.playing=false;s.revision++;controls();render();$('feedback').textContent='เปิด Test แล้ว ล็อกโมเดล ไม่ใช้คะแนนTestกลับไปจูน';});$('test').disabled=Boolean(s.holdout);}}
function train(epoch){let record;const goal=s.batch.epoch+1;do{record=nextBatch(s.batch,s.rate);s.batch=record.next;}while(epoch&&s.batch.epoch<goal);s.record=record;if(s.batch.epoch>=1)seen.add('batch'+s.batch.size);s.step=0;s.playing=false;s.revision++;render();}
function open(topic){s=fresh(topic);const c=content[topic];for(const id of ['title','intro','limits','task'])$(id).textContent=c[id];$('terms').innerHTML=c.terms.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('');$('source').href=c.source;$('feedback').textContent='';document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.topic===topic)));controls();render();}
function advance(){if(s.step<2)s.step++;else s.playing=false;render();}
document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>open(b.dataset.topic));$('next').onclick=()=>{s.playing=false;advance();};$('previous').onclick=()=>{s.playing=false;s.step=Math.max(0,s.step-1);render();};$('play').onclick=()=>{if(!s.playing&&s.step===2)s.step=0;s.playing=!s.playing;render();};$('speed').onchange=()=>s.speed=Number($('speed').value);$('reset').onclick=()=>open(s.topic);$('view').onclick=()=>scene?.resetView();$('check').onclick=()=>{const ok=s.topic==='batch'?seen.has('batch2')&&seen.has('batch8'):seen.has('degree1')&&seen.has('degree7')&&s.fit.degree===3&&Boolean(s.holdout);$('feedback').textContent=ok?'✓ ทดลองครบตามภารกิจ อธิบายได้ไหมว่าชุดไหนใช้ฝึก/เลือก/ประเมิน':'ยังไม่ครบ · ทำตามขนาดBatchหรือDegreeที่กำหนดก่อนตรวจ';};
open('batch');try{const {mountTrainingScene}=await import('./ai-training-scene.js');scene=mountTrainingScene($('stage'),()=>s,advance);}catch(e){$('fallback').hidden=false;$('play').disabled=true;}addEventListener('pagehide',()=>scene?.dispose());
